INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ»', 'O Allaah, ik zoek toevlucht bij U tegen het verdwijnen van Uw gunst, het wegkeren van Uw welzijn, het plotselinge van Uw bestraffing en heel Uw toorn.', 'O Allaah, I seek refuge in You from the removal of Your favour, the shifting of Your wellbeing, the suddenness of Your punishment, and all of Your wrath.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من زوال النعمة', 'onbeperkt', 'unrestricted', 1, 341),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْهَرَمِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ»', 'O Allaah, ik zoek toevlucht bij U tegen onvermogen en luiheid, tegen lafheid, aftakelende ouderdom en gierigheid; en ik zoek toevlucht bij U tegen de bestraffing van het graf en tegen de beproeving van het leven en de dood.', 'O Allaah, I seek refuge in You from incapacity and laziness, from cowardice, decrepit old age and miserliness; and I seek refuge in You from the punishment of the grave and from the trial of life and death.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة الجامعة', 'onbeperkt', 'unrestricted', 1, 342),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا»', 'O Allaah, ik zoek toevlucht bij U tegen kennis die niet baat, een hart dat niet deemoedig is, een ziel die niet verzadigd raakt en een smeekbede die niet wordt verhoord.', 'O Allaah, I seek refuge in You from knowledge that does not benefit, a heart that is not humble, a soul that is never satisfied, and a supplication that is not answered.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من علم لا ينفع', 'onbeperkt', 'unrestricted', 1, 343),('comprehensive', 'general', '«يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ»', 'O Omkeerder van de harten, maak mijn hart standvastig op Uw godsdienst.', 'O Turner of hearts, make my heart firm upon Your religion.', '', '', '', 'في تتمة الحديث علة المداومة عليه: تقلّب القلوب بين أصابع الرحمن.', 'In het vervolg van de hadieth de reden voor de volharding erop: de omkering van de harten tussen de vingers van de Barmhartige.', 'In the hadeeth''s continuation is the reason for persisting on it: the turning of hearts between the fingers of the Most Merciful.', 'وكان أكثر دعائه', 'onbeperkt', 'unrestricted', 1, 344),('comprehensive', 'general', '«اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي»', 'O Allaah, leid mij en maak mij trefzeker — en in een andere bewoording: O Allaah, ik vraag U om leiding en trefzekerheid.', 'O Allaah, guide me and make me accurate — and in another wording: O Allaah, I ask You for guidance and precision.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالهدى والسداد', 'onbeperkt', 'unrestricted', 1, 345),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا»', 'O Allaah, ik vraag U om al het goede, het spoedige en het latere ervan, wat ik ervan weet en wat ik niet weet; en ik zoek toevlucht bij U tegen al het kwade, het spoedige en het latere ervan, wat ik ervan weet en wat ik niet weet. O Allaah, ik vraag U om het beste dat Uw dienaar en Profeet U heeft gevraagd, en ik zoek toevlucht bij U tegen het kwaad waartegen Uw dienaar en Profeet toevlucht zocht. O Allaah, ik vraag U om het Paradijs en om elke uitspraak of daad die daarnaartoe brengt, en ik zoek toevlucht bij U tegen het Vuur en tegen elke uitspraak of daad die daarnaartoe brengt; en ik vraag U dat U elke beschikking die U voor mij beschikt, goed maakt.', 'O Allaah, I ask You for all good, the immediate and the deferred, what I know of it and what I do not; and I seek refuge in You from all evil, the immediate and the deferred, what I know of it and what I do not. O Allaah, I ask You for the best of what Your slave and Prophet asked You, and I seek refuge in You from the evil against which Your slave and Prophet sought refuge. O Allaah, I ask You for Paradise and whatever word or deed brings near to it, and I seek refuge in You from the Fire and whatever word or deed brings near to it; and I ask You to make every decree You decree for me good.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بجوامع الخير', 'onbeperkt', 'unrestricted', 1, 346),('comprehensive', 'general', '«اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ، وَقُدْرَتِكَ عَلَى الْخَلْقِ، أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ، فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ»', 'O Allaah, bij Uw kennis van het verborgene en Uw macht over de schepping: laat mij leven zolang U weet dat het leven beter voor mij is, en neem mij weg wanneer U weet dat het sterven beter voor mij is. O Allaah, ik vraag U om vrees voor U in het verborgene en het openbare, om het woord van waarheid in tevredenheid en woede, om matigheid in rijkdom en armoede; ik vraag U om een genieting die niet opraakt en een oogverkoeling die niet ophoudt; ik vraag U om tevredenheid na de beschikking, om een aangenaam leven na de dood, om het genot van het aanschouwen van Uw Aangezicht en het verlangen naar Uw ontmoeting — zonder schadelijke tegenspoed en zonder misleidende beproeving. O Allaah, sier ons met het sieraad van het geloof en maak ons geleide gidsen.', 'O Allaah, by Your knowledge of the unseen and Your power over creation: keep me alive so long as You know life is better for me, and take me when You know death is better for me. O Allaah, I ask You for fear of You in secret and in public, the word of truth in pleasure and anger, moderation in wealth and poverty; I ask You for bliss that never ends and comfort of the eye that never ceases; I ask You for contentment after the decree, a pleasant life after death, the delight of gazing at Your Face and longing to meet You — without harmful adversity or misleading trial. O Allaah, adorn us with the adornment of faith and make us guides who are rightly guided.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء عمار الجامع', 'onbeperkt', 'unrestricted', 1, 347),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَلِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ»', 'O Allaah, ik vraag U om standvastigheid in de zaak en om vastberadenheid op het rechte pad; ik vraag U om wat Uw barmhartigheid verplicht maakt en om wat Uw vergeving verzekert; ik vraag U om dankbaarheid voor Uw gunst en om het goed aanbidden van U; ik vraag U om een zuiver hart en een waarachtige tong; ik vraag U om het beste van wat U weet, ik zoek toevlucht bij U tegen het kwade van wat U weet, en ik vraag U vergeving voor wat U weet; waarlijk, U bent de Kenner van al het verborgene.', 'O Allaah, I ask You for firmness in the affair and resolve upon right guidance; I ask You for what makes Your mercy binding and what secures Your forgiveness; I ask You for gratitude for Your favour and excellence in worshipping You; I ask You for a sound heart and a truthful tongue; I ask You for the best of what You know, I seek refuge in You from the evil of what You know, and I seek Your forgiveness for what You know; indeed You are the Knower of all unseen.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالثبات والعزيمة', 'onbeperkt', 'unrestricted', 1, 348),('comprehensive', 'general', '«اللَّهُمَّ جَنِّبْنِي مُنْكَرَاتِ الْأَخْلَاقِ، وَالْأَعْمَالِ، وَالْأَهْوَاءِ، وَالْأَدْوَاءِ»', 'O Allaah, houd mij ver van de verwerpelijkheden van karakter, daden, begeerten en ziekten.', 'O Allaah, keep me away from evil character, deeds, desires and diseases.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من منكرات الأخلاق', 'onbeperkt', 'unrestricted', 1, 349),('comprehensive', 'general', '«اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا»', 'O Allaah, deel ons van de vrees voor U toe wat tussen ons en Uw ongehoorzaamheden een barrière vormt; van de gehoorzaamheid aan U wat ons Uw Paradijs doet bereiken; en van de zekerheid wat de rampen van de wereld licht voor ons maakt. Laat ons genieten van ons gehoor, ons zicht en onze kracht zolang U ons laat leven, en maak dat tot onze erfgenaam. Richt onze vergelding op wie ons onrecht heeft aangedaan en help ons tegen wie ons vijandig is. Maak onze beproeving niet in ons geloof, maak de wereld niet onze grootste zorg noch het uiterste van onze kennis, en geef niemand die ons niet genadig is macht over ons.', 'O Allaah, apportion to us such fear of You as will bar us from disobeying You; such obedience to You as will bring us to Your Paradise; and such certainty as will lighten for us the calamities of this world. Grant us enjoyment of our hearing, sight and strength as long as You keep us alive, and make it our inheritor. Let our retaliation be upon whoever wronged us, aid us against whoever shows us enmity, make not our affliction in our religion, make not this world our greatest concern nor the extent of our knowledge, and give no power over us to those who will not show us mercy.', '', '', '', 'كان دعاءه صلى الله عليه وسلم لأصحابه عند القيام من عامة مجالسه.', 'Het was zijn smeekbede (vrede en zegeningen zij met hem) voor zijn metgezellen bij het opstaan van de meeste van zijn bijeenkomsten.', 'It was his supplication (peace and blessings be upon him) for his companions when rising from most of his gatherings.', 'الدعاء بقسمة الخشية والطاعة', 'onbeperkt', 'unrestricted', 1, 350),('comprehensive', 'general', '«رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الْهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ»', 'Mijn Heer, help mij en help niet tegen mij; sta mij bij en sta niet tegen mij bij; beraam ten gunste van mij en beraam niet tegen mij; leid mij en maak de leiding gemakkelijk voor mij, en help mij tegen wie mij onrecht aandoet. Mijn Heer, maak mij U zeer dankbaar, U veelvuldig gedenkend, U zeer vrezend, U volkomen gehoorzaam, aan U onderworpen, verzuchtend en berouwvol terugkerend. Mijn Heer, aanvaard mijn berouw, was mijn zonde weg, verhoor mijn smeekbede, bevestig mijn bewijsvoering, leid mijn hart, maak mijn tong trefzeker en verwijder de kwaadaardigheid uit mijn hart.', 'My Lord, aid me and do not aid against me; support me and do not support against me; devise for me and not against me; guide me and make guidance easy for me, and help me against whoever transgresses against me. My Lord, make me ever grateful to You, ever mindful of You, ever fearful of You, fully obedient to You, humbled before You, oft-sighing and penitent. My Lord, accept my repentance, wash away my sin, answer my supplication, establish my proof, guide my heart, make my tongue true, and remove the malice of my heart.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ومن جوامع دعائه ﷺ', 'onbeperkt', 'unrestricted', 1, 351),('comprehensive', 'general', '«اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي، وَارْزُقْنِي»', 'O Allaah, vergeef mij, wees mij genadig, leid mij, schenk mij gezondheid en voorzie mij — deze verzamelen voor jou je wereldse leven en je Hiernamaals.', 'O Allaah, forgive me, have mercy on me, guide me, grant me wellbeing and provide for me — these gather for you your world and your Hereafter.', '', '', '', 'الفضل منصوص: «فإن هؤلاء تجمع لك دنياك وآخرتك».', 'De verdienste is uitdrukkelijk: ''want deze verzamelen voor jou je wereld en je Hiernamaals''.', 'The merit is stated: ''for these gather for you your world and your Hereafter''.', 'وعلّم ﷺ من أسلم أن يقول', 'onbeperkt', 'unrestricted', 1, 352),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ، وَفِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ، وَمِنْ شَرِّ فِتْنَةِ الْغِنَى، وَمِنْ شَرِّ فِتْنَةِ الْفَقْرِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ»', 'O Allaah, ik zoek toevlucht bij U tegen de beproeving van het Vuur en zijn bestraffing, tegen de beproeving van het graf en zijn bestraffing, tegen het kwaad van de beproeving van rijkdom en het kwaad van de beproeving van armoede, en tegen het kwaad van de beproeving van de masieh ad-dadjdjaal...', 'O Allaah, I seek refuge in You from the trial of the Fire and its punishment, the trial of the grave and its punishment, from the evil of the trial of wealth and the evil of the trial of poverty, and from the evil of the trial of the false messiah...', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من الفتن', 'onbeperkt', 'unrestricted', 1, 353),('comprehensive', 'general', '«اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، اللَّهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ لَا إِلَهَ إِلَّا أَنْتَ أَنْ تُضِلَّنِي، أَنْتَ الْحَيُّ الَّذِي لَا يَمُوتُ، وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ»', 'O Allaah, aan U heb ik mij overgegeven, in U geloof ik, op U vertrouw ik, tot U keer ik terug en omwille van U twist ik. O Allaah, ik zoek toevlucht bij Uw macht — er is geen god behalve U — dat U mij laat dwalen. U bent de al-Levende (al-Hayy) Die niet sterft, terwijl de djinn en de mensen sterven.', 'O Allaah, to You I have submitted, in You I believe, upon You I rely, to You I turn, and by You I contend. O Allaah, I seek refuge in Your might — none has the right to be worshipped except You — lest You leave me astray. You are the Living who does not die, while jinn and men die.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء التهجد', 'onbeperkt', 'unrestricted', 1, 354),('comprehensive', 'general', '«يَا مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ»', 'O Bestuurder van de harten, wend onze harten tot Uw gehoorzaamheid.', 'O Director of hearts, direct our hearts to Your obedience.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وكان أكثر دعائه بمنى وعرفات وغيرهما', 'onbeperkt', 'unrestricted', 1, 355),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ، وَتَرْكَ الْمُنْكَرَاتِ، وَحُبَّ الْمَسَاكِينِ، وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي، وَإِذَا أَرَدْتَ فِتْنَةَ قَوْمٍ فَتَوَفَّنِي غَيْرَ مَفْتُونٍ، وَأَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَحُبَّ عَمَلٍ يُقَرِّبُ إِلَى حُبِّكَ»', 'O Allaah, ik vraag U om het verrichten van de goede daden, het nalaten van de verwerpelijkheden en de liefde voor de armen; dat U mij vergeeft en mij genadig bent; en wanneer U een volk wilt beproeven, neem mij dan onbeproefd tot U. En ik vraag U om Uw liefde, om de liefde van wie U liefheeft, en om de liefde voor elke daad die tot Uw liefde nader brengt.', 'O Allaah, I ask You for the doing of good deeds, the leaving of evils, and love of the poor; that You forgive me and have mercy on me; and when You will a people''s trial, take me untried. And I ask You for Your love, the love of those who love You, and the love of every deed that draws near to Your love.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ومن دعاء رؤيا اختصام الملأ الأعلى', 'onbeperkt', 'unrestricted', 1, 356),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَدْمِ، وَأَعُوذُ بِكَ مِنَ التَّرَدِّي، وَأَعُوذُ بِكَ مِنَ الْغَرَقِ وَالْحَرَقِ وَالْهَرَمِ، وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا»', 'O Allaah, ik zoek toevlucht bij U tegen bedolven worden, tegen neerstorten, tegen verdrinken, verbranden en aftakelende ouderdom; ik zoek toevlucht bij U ertegen dat de shaytaan mij bij de dood verwart; ik zoek toevlucht bij U ertegen dat ik op Uw weg sterf terwijl ik de rug toekeer; en ik zoek toevlucht bij U ertegen dat ik door een beet sterf.', 'O Allaah, I seek refuge in You from being crushed, from falling, from drowning, burning and decrepitude; I seek refuge in You lest Satan confound me at death; I seek refuge in You from dying in Your cause while fleeing; and I seek refuge in You from dying stung.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ومن استعاذاته ﷺ من ميتات السوء', 'onbeperkt', 'unrestricted', 1, 357),('comprehensive', 'general', '«تَعَوَّذُوا بِاللَّهِ مِنْ جَارِ السُّوءِ فِي دَارِ الْمُقَامَةِ؛ فَإِنَّ جَارَ الْبَادِيَةِ يَتَحَوَّلُ عَنْكَ»، وَفِي لَفْظٍ: «اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ سُوءٍ فِي دَارِ إِقَامَةٍ»', 'O Allaah, ik zoek toevlucht bij U tegen een slechte buur in de vaste woonplaats; want de buur in de woestijn verhuist weer.', 'O Allaah, I seek refuge in You from an evil neighbour in the permanent abode; for the desert neighbour moves away.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'والاستعاذة من جار السوء', 'onbeperkt', 'unrestricted', 1, 358),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ؛ فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ»', 'O Allaah, ik vraag U om Uw gunst en Uw barmhartigheid; want niemand bezit ze behalve U.', 'O Allaah, I ask You of Your bounty and Your mercy; for none possesses them except You.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا خرج قدّم رجله اليسرى وقال', 'onbeperkt', 'unrestricted', 1, 359),('comprehensive', 'general', '«اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا، وَالْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، وَأَعُوذُ بِاللَّهِ مِنْ حَالِ أَهْلِ النَّارِ»', 'O Allaah, laat mij baat hebben bij wat U mij heeft onderwezen, onderwijs mij wat mij baat en vermeerder mij in kennis. Alle lof zij Allaah in elke toestand, en ik zoek toevlucht bij Allaah tegen de toestand van de mensen van het Vuur.', 'O Allaah, benefit me by what You have taught me, teach me what benefits me, and increase me in knowledge. Praise be to Allaah in every state, and I seek refuge in Allaah from the state of the people of the Fire.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالنفع بالعلم', 'onbeperkt', 'unrestricted', 1, 360);